/**
 * Carte de déplacement piéton du modèle urbain "Secteur – ville nouvelle".
 * Générée à partir de la géométrie du modèle (vue du dessus, cases de 1 m) :
 *   - sol de voirie / trottoir / pavé / pelouse = praticable,
 *   - emprise des bâtiments, haies, troncs, mobilier = obstacle,
 *   - seule la plus grande zone connexe est conservée.
 * Une case = 1 octet : bits 0-2 = classe de sol (0 bloqué, 1 chaussée, 2 parking, 3 trottoir/pavé, 4 pelouse),
 * bit 3 = couvert arboré. Compression par plages (valeur u8, longueur u16 little-endian), puis base64.
 * Origine : coin (x = -260 m, z = -263 m) du modèle ; l'axe y de la simulation suit l'axe z du modèle.
 */
export const WALK_MAP_WIDTH = 520;
export const WALK_MAP_HEIGHT = 525;
export const WALK_MAP_B64 =
  '';
